void ScriptActions::doTeamUseCommandButtonOnNearestEnemy(
	const AsciiString &teamName, const AsciiString &commandAbility)
{
	Team *team = TheScriptEngine->getTeamNamed(teamName, false);
	if (!team)
		return;

	AIGroup *theGroup = bfmeCreateGroup(TheAI);
	bfmeGetTeamAsAIGroup(team, theGroup);

	const CommandButton *commandButton = bfmeFindCommandButton(TheControlBar, commandAbility);
	if (!commandButton)
		return;

	Object *srcObj;
	if (commandButton->getSpecialPowerTemplate()) {
		srcObj = bfmeGetSpecialPowerSourceObject(theGroup, commandButton->getSpecialPowerTemplate()->getID());
	} else {
		srcObj = bfmeGetCommandButtonSourceObject(theGroup, commandButton->getCommandType());
	}

	if (!srcObj)
		return;
	if (!bfmeCommandButtonIsReady(commandButton, srcObj))
		return;

	Coord3D center;
	bfmeGetCenter(theGroup, &center);

	const VptrZeroBlock24 enemyUnitMask = { 0, 0x00200000, 0x01000000, 0, 2, 0 };
	const VptrZeroBlock24 emptyMask = *(const VptrZeroBlock24 *)&KINDOFMASK_NONE;

	if ((commandButton->getOptions() & 0x20) != 0) {
		PartitionFilterSameMapStatus mapFilter(srcObj);
		Rva000C3DD0VptrZeroBlockObject kindFilter(emptyMask, enemyUnitMask);
		Object *target = ThePartitionManager->getClosestObject(
			&center, 1000000.0f, 0,
			PartitionFilterPlayerAffiliation(bfmeGetControllingPlayer(team), ALLOW_ENEMIES, true).link(
				kindFilter.link(&mapFilter)));
		if (target)
			bfmeGroupDoCommandButtonAtObject(theGroup, commandButton, target, CMD_FROM_SCRIPT);
	} else {
		PartitionFilterSameMapStatus mapFilter(srcObj);
		Rva000C3DD0VptrZeroBlockObject kindFilter(emptyMask, enemyUnitMask);
		PartitionFilterValidCommandButtonTarget validFilter(srcObj, commandButton, true, CMD_FROM_SCRIPT);
		Object *target = ThePartitionManager->getClosestObject(
			&center, 1000000.0f, 0,
			PartitionFilterPlayerAffiliation(bfmeGetControllingPlayer(team), ALLOW_ENEMIES, true).link(
				validFilter.link(kindFilter.link(&mapFilter))));
		if (target)
			bfmeGroupDoCommandButtonAtObject(theGroup, commandButton, target, CMD_FROM_SCRIPT);
	}
